/* ===================== BÀI 12 · Đọc datasheet và ghi chép lab ===================== */
/* ---- công cụ tương tác: chép từ tools/author/nentang/wds.js bởi m03lib.write3 ---- */
/* Bài 12 · Đọc bảng thông số và kết luận phép đo (AMTS-FND-002-SIM12, phần ghi chép lab).
   Mọi số trong bảng là của một vi điều khiển GIẢ ĐỊNH “AMTS-D51” do bài tự đặt ra để luyện đọc datasheet,
   KHÔNG phải số của chip thật nào. Học viên làm lab thật phải dùng datasheet đúng mã và đúng phiên bản của chip mình có.
   NTDS: phần TÍNH (engine), hàm thuần. Kiểm thử: python3 tests/nentang/ref_m03.py && node tests/nentang/test_m03.js.
   makeNtSpec: phần VẼ, chỉ gọi NTDS.
   Quy tắc kết luận (theo thứ tự): VCC ngoài giới hạn tuyệt đối (cận trên hoặc cận dưới) hoặc |dòng chân| vượt giới hạn → "nguy";
   VCC hoặc nhiệt độ ngoài điều kiện làm việc → "khong-so"; điều kiện đo (dòng tải, tần số) khác dòng bảng → "khong-so";
   còn lại so với min và / hoặc max → "dat" hoặc "khong-dat".
   Giới hạn: abs.vcc là số (chỉ cận trên) hoặc [min, max]; không kiểm điện áp trên chân, nhiệt độ bảo quản (không có ô nhập);
   điều kiện làm việc là một khoảng duy nhất cho mỗi dòng (bảng giả định chỉ có đặc tính cho mã …C, 0…70 °C). */
const NTDS={
  EPS:1e-9,
  num(s){s=String(s==null?"":s).trim().replace(",",".").replace("−","-");return/^[-+]?(\d+\.?\d*|\.\d+)$/.test(s)?Number(s):NaN},
  /* row: {p, unit, min?, max?, cond:{i?, f?}, op:{vcc:[lo,hi], ta:[lo,hi]}, abs:{vcc: hi | [lo,hi], i}}; c: {vcc, ta, i?, f?}; m: số đo */
  judge(row,c,m){const E=NTDS.EPS,a=row.abs||{},op=row.op||{},rc=row.cond||{};
    if(![c.vcc,c.ta,m].every(Number.isFinite))return{v:"loi",why:"input"};
    const av=Array.isArray(a.vcc)?a.vcc:[null,a.vcc];
    if(av[1]!=null&&c.vcc>av[1]+E)return{v:"nguy",why:"abs-vcc"};
    if(av[0]!=null&&c.vcc<av[0]-E)return{v:"nguy",why:"abs-vcc-lo"};
    if(a.i!=null&&c.i!=null&&Math.abs(c.i)>a.i+E)return{v:"nguy",why:"abs-i"};
    if(op.vcc&&(c.vcc<op.vcc[0]-E||c.vcc>op.vcc[1]+E))return{v:"khong-so",why:"op-vcc"};
    if(op.ta&&(c.ta<op.ta[0]-E||c.ta>op.ta[1]+E))return{v:"khong-so",why:"op-ta"};
    if(rc.i!=null&&!(c.i!=null&&Math.abs(c.i-rc.i)<=E))return{v:"khong-so",why:"cond-i"};
    if(rc.f!=null&&!(c.f!=null&&Math.abs(c.f-rc.f)<=E))return{v:"khong-so",why:"cond-f"};
    if(row.max!=null&&m>row.max+E)return{v:"khong-dat",why:"max",margin:row.max-m};
    if(row.min!=null&&m<row.min-E)return{v:"khong-dat",why:"min",margin:m-row.min};
    return{v:"dat",why:"ok",margin:Math.min(row.max!=null?row.max-m:Infinity,row.min!=null?m-row.min:Infinity)}},
  /* thông số timing dạng k·tCLCL − c (ns), tCLCL = 1000 / f(MHz) ns */
  timing(f,k,c){return k*1000/f-c},
  f(x,d){if(!Number.isFinite(x))return"—";let s=x.toFixed(d==null?2:d);if(s.includes("."))s=s.replace(/0+$/,"").replace(/\.$/,"");return s.replace(".",",").replace("-","−")},
  WHY:{ok:"nằm trong giới hạn của bảng ở đúng điều kiện đo",max:"lớn hơn giá trị max của bảng",min:"nhỏ hơn giá trị min của bảng",
    "cond-i":"dòng tải khi đo khác dòng tải ghi trong bảng: bảng không nói gì về điều kiện này","cond-f":"tần số khi đo khác tần số ghi trong bảng",
    "op-vcc":"VCC ngoài điều kiện làm việc khuyến nghị: bảng đặc tính không bảo đảm","op-ta":"nhiệt độ ngoài dải của mã chip này: bảng không bảo đảm",
    "abs-vcc":"VCC vượt giới hạn tuyệt đối: có thể làm hỏng chip, dừng thí nghiệm","abs-vcc-lo":"VCC thấp hơn cận dưới của giới hạn tuyệt đối (ví dụ nối ngược nguồn): có thể làm hỏng chip, dừng thí nghiệm","abs-i":"dòng chân vượt giới hạn tuyệt đối: có thể làm hỏng chân, dừng thí nghiệm",input:"thiếu hoặc sai một số"},
  NAME:{dat:"Đạt","khong-dat":"Không đạt","khong-so":"Không so được",nguy:"Vượt giới hạn tuyệt đối",loi:"Chưa đủ dữ liệu"}
};
function makeNtSpec(el,cfg){
  const ID="nds-"+(cfg.id||"x"),R=cfg.rows,G=cfg.grades,E=window.esc||(s=>String(s));
  el.classList.add("n3-ds");
  el.innerHTML=`<p class="n3-h">Kết luận một phép đo theo bảng (chip giả định ${E(cfg.chip)})</p>
   <div class="n3-grid"><label>Thông số<select id="${ID}-row">${R.map((r,i)=>`<option value="${i}">${E(r.label)}</option>`).join("")}</select></label>
   <label>VCC khi đo (V)<input id="${ID}-vcc" inputmode="decimal" autocomplete="off"></label>
   <label>Nhiệt độ môi trường (°C)<input id="${ID}-ta" inputmode="decimal" autocomplete="off"></label>
   <label id="${ID}-il">Dòng tải khi đo (mA)<input id="${ID}-i" inputmode="decimal" autocomplete="off"></label>
   <label>Giá trị đo được<input id="${ID}-m" inputmode="decimal" autocomplete="off"></label></div>
   <p class="n3-verdict" id="${ID}-v" role="status" aria-live="polite"></p>
   <p class="n3-h">Tính thông số thời gian theo tCLCL</p>
   <div class="n3-grid"><label>Mã đặt hàng<select id="${ID}-g">${G.map((g,i)=>`<option value="${i}">${E(g.code)}</option>`).join("")}</select></label>
   <label>Tần số thạch anh (MHz)<input id="${ID}-f" inputmode="decimal" autocomplete="off" value="12"></label></div>
   <div class="n3-dstab" id="${ID}-t" aria-live="polite"></div>`;
  const $=x=>el.querySelector("#"+ID+"-"+x),N=NTDS.num;
  function setRow(){const r=R[+$("row").value];$("vcc").value=NTDS.f(r.def.vcc);$("ta").value=NTDS.f(r.def.ta);
    $("il").hidden=r.cond.i==null;$("i").value=r.cond.i==null?"":NTDS.f(r.cond.i);$("m").value="";judge()}
  function judge(){const r=R[+$("row").value],c={vcc:N($("vcc").value),ta:N($("ta").value)};if(r.cond.i!=null)c.i=N($("i").value);
    const mv=$("m").value.trim();if(!mv){$("v").className="n3-verdict warn";$("v").textContent=`Bảng: ${r.text}. Nhập giá trị đo để kết luận.`;return}
    const x=NTDS.judge(r,c,N(mv)),cls={dat:"ok","khong-dat":"bad","khong-so":"warn",nguy:"bad",loi:"warn"}[x.v];
    $("v").className="n3-verdict "+cls;
    $("v").textContent=`${NTDS.NAME[x.v]}: ${NTDS.WHY[x.why]}.`+(x.margin!=null&&x.v==="dat"?` Còn cách giới hạn ${NTDS.f(x.margin,3)} ${r.unit}.`:"")+` (Bảng: ${r.text}.)`}
  function timing(){const g=G[+$("g").value],f=N($("f").value);
    if(!(f>0)){$("t").innerHTML='<p class="n3-verdict warn">Nhập tần số lớn hơn 0.</p>';return}
    const t=1000/f,warn=f>g.fmax+1e-9;
    $("t").innerHTML=(warn?`<p class="n3-verdict bad">${NTDS.f(f)} MHz vượt tần số lớn nhất ${g.fmax} MHz của mã ${E(g.code)}: các số dưới đây không được bảo đảm.</p>`:"")+
      `<table class="mt-tab"><thead><tr><th scope="col">Đại lượng</th><th scope="col">Công thức (giả định)</th><th scope="col">Giá trị</th></tr></thead><tbody>
      <tr><td>tCLCL</td><td>1 / f</td><td>${NTDS.f(t)} ns</td></tr>
      <tr><td>1 chu kỳ máy</td><td>12 tCLCL</td><td>${NTDS.f(12*t/1000,4)} µs</td></tr>
      ${cfg.timing.map(p=>`<tr><td>${E(p.p)} (${p.mm})</td><td>${p.k===1?"":p.k} tCLCL − ${p.c} ns</td><td${NTDS.timing(f,p.k,p.c)<0?' class="bad"':""}>${NTDS.f(NTDS.timing(f,p.k,p.c))} ns</td></tr>`).join("")}</tbody></table>`}
  $("row").onchange=setRow;["vcc","ta","i","m"].forEach(k=>$(k).addEventListener("input",judge));
  $("g").onchange=timing;$("f").addEventListener("input",timing);
  setRow();timing()}
/* ---- dữ liệu và lời gọi của bài ---- */
/* Bài 12 · Đọc datasheet và ghi chép lab (FND-012) — sinh bởi tools/author/nentang/m12.py, không sửa tay.
   Bảng bit tương tác, phòng mô phỏng từng bước và bài tập chấm tự động; phần chữ bài học ở lesson.html (nội dung bảo vệ). */
makeNtSpec(document.getElementById("ds-l12"),{"id": "l12", "chip": "AMTS-D51", "rows": [{"p": "VOL", "label": "VOL ở IOL = 2 mA", "unit": "V", "max": 0.4, "cond": {"i": 2.0}, "text": "VOL ≤ 0,40 V khi IOL = 2 mA, VCC = 4,5…5,5 V, TA = 0…70 °C", "def": {"vcc": 5.0, "ta": 25.0}, "op": {"vcc": [4.5, 5.5], "ta": [0, 70]}, "abs": {"vcc": [-0.5, 6.5], "i": 10.0}}, {"p": "VOL", "label": "VOL ở IOL = 6 mA", "unit": "V", "max": 0.6, "cond": {"i": 6.0}, "text": "VOL ≤ 0,60 V khi IOL = 6 mA, VCC = 4,5…5,5 V, TA = 0…70 °C", "def": {"vcc": 5.0, "ta": 25.0}, "op": {"vcc": [4.5, 5.5], "ta": [0, 70]}, "abs": {"vcc": [-0.5, 6.5], "i": 10.0}}, {"p": "VOH", "label": "VOH ở IOH = −80 µA", "unit": "V", "min": 2.4, "cond": {"i": -0.08}, "text": "VOH ≥ 2,4 V khi IOH = −80 µA (dòng chảy ra), VCC = 4,5…5,5 V, TA = 0…70 °C", "def": {"vcc": 5.0, "ta": 25.0}, "op": {"vcc": [4.5, 5.5], "ta": [0, 70]}, "abs": {"vcc": [-0.5, 6.5], "i": 10.0}}], "grades": [{"code": "AMTS-D51-24PC", "fmax": 24, "ta": [0, 70], "pkg": "PDIP 40 chân"}, {"code": "AMTS-D51-33JI", "fmax": 33, "ta": [-40, 85], "pkg": "PLCC 44 chân"}], "timing": [{"p": "tLHLL", "mm": "min", "k": 2, "c": 35, "ten": "độ rộng xung ALE"}, {"p": "tAVLL", "mm": "min", "k": 1, "c": 20, "ten": "địa chỉ ổn định trước khi ALE xuống"}]});
makeMtLab(document.getElementById("lab-l12"),{id:"l12",scenarios:[{"label": "Ví dụ: Mã đặt hàng và phiên bản tài liệu", "note": "Phần đuôi mã chip cho biết tần số, vỏ, dải nhiệt độ.", "steps": [{"t": "Mã đặt hàng mã hóa tần số, vỏ, dải nhiệt độ", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Mã đặt hàng<\/th><th scope=\"col\">f max<\/th><th scope=\"col\">Vỏ<\/th><th scope=\"col\">Nhiệt độ<\/th><\/tr><\/thead><tbody><tr><td>AMTS-D51-24PC<\/td><td>24 MHz<\/td><td>PDIP 40 chân<\/td><td>0 … 70 °C<\/td><\/tr><tr><td>AMTS-D51-33JI<\/td><td>33 MHz<\/td><td>PLCC 44 chân<\/td><td>-40 … 85 °C<\/td><\/tr><\/tbody><\/table><p class=\"mt-cap\"><b>Giả định:<\/b> chip AMTS-D51 và mọi số trong bảng do bài tự đặt ra để luyện đọc, không phải số của chip thật.<\/p>", "say": "<p>Cùng một tên chip có nhiều biến thể. Phần đuôi của mã đặt hàng thường cho biết tần số lớn nhất, kiểu vỏ, dải nhiệt độ; cách mã hóa của mỗi hãng khác nhau, phải tra bảng “Ordering information” của đúng datasheet.<\/p>"}, {"t": "Lịch sử phiên bản của tài liệu", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Phiên bản<\/th><th scope=\"col\">Thay đổi<\/th><\/tr><\/thead><tbody><tr><td>Rev. A<\/td><td>bản đầu<\/td><\/tr><tr><td>Rev. B<\/td><td>thêm mã -33JI<\/td><\/tr><tr><td>Rev. C<\/td><td>sửa VOL ở IOL = 6 mA từ 0,65 V thành 0,60 V<\/td><\/tr><\/tbody><\/table><p class=\"mt-cap\"><b>Giả định:<\/b> chip AMTS-D51 và mọi số trong bảng do bài tự đặt ra để luyện đọc, không phải số của chip thật.<\/p>", "ask": {"q": "Thiết bị phải chạy ở −20 °C. Chọn mã nào?", "o": ["AMTS-D51-24PC", "Mã nào cũng được", "AMTS-D51-33JI"], "a": 2}, "say": "<p>Datasheet cũng có phiên bản. Ghi mã đặt hàng đầy đủ và phiên bản tài liệu vào phiếu lab: một con số có thể đổi giữa hai bản (Ví dụ 9).<\/p>"}]}, {"label": "Ví dụ: Bốn bảng của một datasheet", "note": "Giới hạn tuyệt đối, điều kiện làm việc, đặc tính DC, đặc tính AC.", "steps": [{"t": "Bảng 1: giới hạn tuyệt đối", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Thông số (giới hạn tuyệt đối)<\/th><th scope=\"col\">Giá trị<\/th><\/tr><\/thead><tbody><tr><td>VCC so với GND<\/td><td>−0,5 … 6,5 V<\/td><\/tr><tr><td>Điện áp trên chân bất kỳ<\/td><td>−0,5 … VCC + 0,5 V<\/td><\/tr><tr><td>Dòng mỗi chân cổng<\/td><td>10 mA<\/td><\/tr><tr><td>Nhiệt độ bảo quản<\/td><td>−65 … 150 °C<\/td><\/tr><\/tbody><\/table><p class=\"mt-cap\"><b>Giả định:<\/b> chip AMTS-D51 và mọi số trong bảng do bài tự đặt ra để luyện đọc, không phải số của chip thật.<\/p>", "say": "<p><b>Absolute Maximum Ratings<\/b>: vượt là có thể hỏng chip. Đây không phải điều kiện làm việc và không bảo đảm chip chạy đúng ở các mức đó.<\/p>"}, {"t": "Bảng 2: điều kiện làm việc", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Điều kiện làm việc<\/th><th scope=\"col\">Min<\/th><th scope=\"col\">Max<\/th><th scope=\"col\">Đơn vị<\/th><\/tr><\/thead><tbody><tr><td>VCC<\/td><td>4,5<\/td><td>5,5<\/td><td>V<\/td><\/tr><tr><td>Nhiệt độ môi trường, mã …C<\/td><td>0<\/td><td>70<\/td><td>°C<\/td><\/tr><tr><td>Nhiệt độ môi trường, mã …I<\/td><td>−40<\/td><td>85<\/td><td>°C<\/td><\/tr><tr><td>Tần số thạch anh, mã -24 / -33<\/td><td>0<\/td><td>24 / 33<\/td><td>MHz<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "VCC = 6,0 V thuộc vùng nào?", "o": ["Trên điều kiện làm việc, dưới giới hạn tuyệt đối: không được bảo đảm", "Trong điều kiện làm việc", "Vượt giới hạn tuyệt đối"], "a": 0}, "say": "<p><b>Recommended Operating Conditions<\/b>: trong vùng này nhà sản xuất bảo đảm các bảng đặc tính.<\/p>"}, {"t": "Bảng 3: đặc tính DC có điều kiện đo", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Ký hiệu<\/th><th scope=\"col\">Thông số<\/th><th scope=\"col\">Điều kiện đo<\/th><th scope=\"col\">Min<\/th><th scope=\"col\">Typ<\/th><th scope=\"col\">Max<\/th><th scope=\"col\">Đơn vị<\/th><\/tr><\/thead><tbody><tr><td>VOL<\/td><td>điện áp ra mức thấp (cổng)<\/td><td>IOL = 2 mA<\/td><td><\/td><td>0,2<\/td><td>0,40<\/td><td>V<\/td><\/tr><tr><td>VOL<\/td><td>điện áp ra mức thấp (cổng)<\/td><td>IOL = 6 mA<\/td><td><\/td><td>0,4<\/td><td>0,60<\/td><td>V<\/td><\/tr><tr><td>VOH<\/td><td>điện áp ra mức cao (cổng)<\/td><td>IOH = −80 µA<\/td><td>2,4<\/td><td><\/td><td><\/td><td>V<\/td><\/tr><\/tbody><\/table><p class=\"mt-cap\">Điều kiện chung của bảng đặc tính: VCC = 4,5…5,5 V, TA = 0…70 °C (mã …C) trừ khi ghi khác. Cột Typ: ước lượng, không bảo đảm.<\/p>", "say": "<p><b>DC Characteristics<\/b>: mỗi dòng chỉ đúng với điều kiện đo ghi kèm. VOL có hai dòng: 0,40 V ở 2 mA và 0,60 V ở 6 mA.<\/p>"}, {"t": "Bảng 4: đặc tính AC (timing) theo tCLCL", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Ký hiệu<\/th><th scope=\"col\">Thông số<\/th><th scope=\"col\">Min<\/th><th scope=\"col\">Max<\/th><\/tr><\/thead><tbody><tr><td>1/tCLCL<\/td><td>tần số thạch anh, mã -24<\/td><td>0<\/td><td>24 MHz<\/td><\/tr><tr><td>tLHLL<\/td><td>độ rộng xung ALE<\/td><td>2tCLCL − 35 ns<\/td><td><\/td><\/tr><tr><td>tAVLL<\/td><td>địa chỉ ổn định trước khi ALE xuống<\/td><td>tCLCL − 20 ns<\/td><td><\/td><\/tr><\/tbody><\/table><p class=\"mt-cap\"><b>Giả định:<\/b> chip AMTS-D51 và mọi số trong bảng do bài tự đặt ra để luyện đọc, không phải số của chip thật.<\/p>", "say": "<p>Thông số thời gian của 8051 thường ghi theo chu kỳ thạch anh tCLCL = 1/f, nên phải tính lại cho tần số mình dùng.<\/p>"}]}, {"label": "Ví dụ: Kết luận một phép đo VOL", "note": "Chọn đúng dòng bảng theo điều kiện đo, tính biên an toàn.", "steps": [{"t": "Phép đo: VOL ở chân P\u0031.0 khi IOL = 2,0 mA", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Đại lượng<\/th><th scope=\"col\">Giá trị đo (giả định)<\/th><\/tr><\/thead><tbody><tr><td>VCC<\/td><td>5,0 V<\/td><\/tr><tr><td>Nhiệt độ<\/td><td>25 °C<\/td><\/tr><tr><td>IOL đặt<\/td><td>2,0 mA<\/td><\/tr><tr><td>VOL đo<\/td><td>0,31 V<\/td><\/tr><\/tbody><\/table>", "say": "<p>Giả định: dòng IOL được đặt bằng một điện trở từ VCC vào chân đang xuất mức 0, kiểm tra bằng đồng hồ đo dòng.<\/p>"}, {"t": "Chọn đúng dòng của bảng: IOL = 2 mA", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Ký hiệu<\/th><th scope=\"col\">Thông số<\/th><th scope=\"col\">Điều kiện đo<\/th><th scope=\"col\">Min<\/th><th scope=\"col\">Typ<\/th><th scope=\"col\">Max<\/th><th scope=\"col\">Đơn vị<\/th><\/tr><\/thead><tbody><tr><td>VOL<\/td><td>điện áp ra mức thấp (cổng)<\/td><td>IOL = 2 mA<\/td><td><\/td><td>0,2<\/td><td>0,40<\/td><td>V<\/td><\/tr><tr><td>VOL<\/td><td>điện áp ra mức thấp (cổng)<\/td><td>IOL = 6 mA<\/td><td><\/td><td>0,4<\/td><td>0,60<\/td><td>V<\/td><\/tr><tr><td>VOH<\/td><td>điện áp ra mức cao (cổng)<\/td><td>IOH = −80 µA<\/td><td>2,4<\/td><td><\/td><td><\/td><td>V<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Giới hạn cần so là gì?", "o": ["VOL ≤ 0,60 V", "VOL ≤ 0,40 V", "VOH ≥ 2,4 V"], "a": 1}}, {"t": "Đạt, còn cách giới hạn 0,09 V", "html": "<p class=\"mt-calc\">0,31 V ≤ 0,40 V → <b>Đạt<\/b> · biên an toàn 0,40 − 0,31 = <b>0,09 V<\/b><\/p>", "say": "<p>Kiểm tra theo thứ tự: không vượt giới hạn tuyệt đối; VCC, nhiệt độ trong điều kiện làm việc; điều kiện đo khớp dòng bảng; rồi mới so min / max. Thử cùng phép đo bằng công cụ ở mục 12.2.<\/p>"}]}, {"label": "Ví dụ: Tính thông số thời gian theo tCLCL", "note": "Thay tần số của mạch vào công thức k·tCLCL − c.", "steps": [{"t": "tCLCL ở 24 MHz", "html": "<p class=\"mt-calc\">tCLCL = 1 / 24 MHz = 1000 / 24 ns = <b>41,67 ns<\/b><\/p>"}, {"t": "tLHLL min = 2tCLCL − 35 ns", "html": "<p class=\"mt-calc\">2 × 41,67 − 35 = <b>48,33 ns<\/b><\/p>", "ask": {"q": "Cũng công thức đó ở 12 MHz cho bao nhiêu?", "o": ["48,33 ns", "24,17 ns", "131,67 ns"], "a": 2}}, {"t": "tAVLL min = tCLCL − 20 ns: ở 24 và 33 MHz", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">f<\/th><th scope=\"col\">tCLCL<\/th><th scope=\"col\">tAVLL min<\/th><\/tr><\/thead><tbody><tr><td>24 MHz<\/td><td>41,67 ns<\/td><td>21,67 ns<\/td><\/tr><tr><td>33 MHz<\/td><td>30,3 ns<\/td><td>10,3 ns<\/td><\/tr><\/tbody><\/table><p class=\"mt-cap\"><b>Giả định:<\/b> chip AMTS-D51 và mọi số trong bảng do bài tự đặt ra để luyện đọc, không phải số của chip thật.<\/p>", "say": "<p>Tần số càng cao thì khoảng thời gian càng ngắn: thiết bị ngoài (bộ nhớ, bộ chốt địa chỉ) phải đủ nhanh. So thông số timing của 8051 với datasheet của thiết bị ngoài học ở khóa 8051.<\/p>"}]}, {"label": "Ví dụ: Chu kỳ máy ở 11,0592 MHz (s51)", "note": "12 tCLCL; đối chiếu thời gian s51 in ra ở ba tần số.", "steps": [{"t": "1 chu kỳ máy = 12 tCLCL (8051 gốc)", "html": "<p class=\"mt-calc\">12 / 12 MHz = 1 µs · 12 / 11,0592 MHz = <b>1,085 µs<\/b><\/p>"}, {"t": "Đối chiếu bằng ucsim s51 ở ba tần số", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">-X (s51)<\/th><th scope=\"col\">Ticks của MOV A,#data<\/th><th scope=\"col\">Thời gian s51 in ra<\/th><\/tr><\/thead><tbody><tr><td>11.0592M<\/td><td>12<\/td><td>1.085e-06 s<\/td><\/tr><tr><td>12M<\/td><td>12<\/td><td>1e-06 s<\/td><\/tr><tr><td>24M<\/td><td>12<\/td><td>5e-07 s<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Thạch anh 11,0592 MHz cho chu kỳ máy dài hơn hay ngắn hơn 1 µs?", "o": ["Dài hơn: 1,085 µs", "Ngắn hơn: 0,92 µs", "Bằng 1 µs"], "a": 0}, "say": "<p>s51 đếm 12 chu kỳ dao động cho lệnh này ở mọi tần số và in thời gian = 12 / f. Chip đời mới có thể dùng ít chu kỳ dao động hơn cho mỗi chu kỳ máy: đọc datasheet của đúng chip (Bài 1).<\/p>"}]}, {"label": "Lỗi: Phiếu lab thiếu điều kiện đo", "note": "Thiếu điều kiện thì không so được với bảng; sửa thành phiếu đủ 7 mục.", "steps": [{"t": "Phiếu lab thiếu thông tin", "html": "<div class=\"n3-sheet\"><p><b>Mục tiêu<\/b> đo VOL<\/p><p class=\"miss\"><b>Linh kiện<\/b> chip 8051<\/p><p class=\"miss\"><b>Điều kiện đo<\/b> (không ghi)<\/p><p class=\"miss\"><b>Dự đoán<\/b> (không ghi)<\/p><p class=\"miss\"><b>Dữ liệu<\/b> khoảng 0,3<\/p><p class=\"miss\"><b>Kết luận<\/b> ổn<\/p><\/div>", "say": "<p>Phiếu này không tái lập được: không rõ chip nào, tài liệu nào, VCC, dòng tải, nhiệt độ; số đo không đơn vị; “ổn” không phải kết luận.<\/p>"}, {"t": "Thiếu điều kiện đo thì không so được với bảng", "html": "<p class=\"mt-calc\">“khoảng 0,3” ở IOL = ? mA, VCC = ? V → không biết so với dòng nào của bảng<\/p>", "ask": {"q": "Mục nào thiếu làm phép đo không so được với datasheet?", "o": ["Tên người đo", "Điều kiện đo (IOL, VCC, nhiệt độ)", "Ngày giờ đo"], "a": 1}}, {"t": "Sửa: phiếu lab đủ mục", "html": "<div class=\"n3-sheet\"><p><b>Mục tiêu<\/b> kiểm tra VOL của P\u0031.0 theo datasheet<\/p><p><b>Linh kiện, tài liệu<\/b> AMTS-D51-24PC, datasheet Rev. C<\/p><p><b>Sơ đồ, điều kiện đo<\/b> P\u0031.0 xuất 0, tải từ VCC đặt IOL = 2,0 mA; VCC = 5,0 V; 25 °C; đồng hồ số thang 2 V<\/p><p><b>Dự đoán<\/b> VOL ≤ 0,40 V (bảng DC, IOL = 2 mA)<\/p><p><b>Dữ liệu thô<\/b> 0,31 V; 0,31 V; 0,32 V (3 lần)<\/p><p><b>So sánh<\/b> lớn nhất 0,32 V ≤ 0,40 V, biên 0,08 V<\/p><p><b>Kết luận, giới hạn<\/b> Đạt ở 25 °C; chưa thử ở 0 °C và 70 °C<\/p><\/div><p class=\"mt-cap\"><b>Giả định:<\/b> chip AMTS-D51 và mọi số trong bảng do bài tự đặt ra để luyện đọc, không phải số của chip thật.<\/p>", "say": "<p>Dữ liệu thô ghi đủ các lần đo, có đơn vị, không xóa lần đo “xấu”. Kết luận nói rõ giới hạn: phép đo mới ở một nhiệt độ. Có thể ghép thêm bảng nhật ký gỡ lỗi của Bài 11 khi kết quả lạ.<\/p>"}]}, {"label": "Bẫy: Coi giới hạn tuyệt đối là điều kiện làm việc", "note": "10 mA tuyệt đối, nhưng VOL chỉ được bảo đảm tới 6 mA.", "steps": [{"t": "“Giới hạn tuyệt đối 10 mA, vậy cho chân chạy 10 mA”", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Thông số (giới hạn tuyệt đối)<\/th><th scope=\"col\">Giá trị<\/th><\/tr><\/thead><tbody><tr><td>VCC so với GND<\/td><td>−0,5 … 6,5 V<\/td><\/tr><tr><td>Điện áp trên chân bất kỳ<\/td><td>−0,5 … VCC + 0,5 V<\/td><\/tr><tr><td>Dòng mỗi chân cổng<\/td><td>10 mA<\/td><\/tr><tr><td>Nhiệt độ bảo quản<\/td><td>−65 … 150 °C<\/td><\/tr><\/tbody><\/table><p class=\"mt-cap\"><b>Giả định:<\/b> chip AMTS-D51 và mọi số trong bảng do bài tự đặt ra để luyện đọc, không phải số của chip thật.<\/p>"}, {"t": "Bảng đặc tính chỉ bảo đảm VOL tới 6 mA", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Ký hiệu<\/th><th scope=\"col\">Thông số<\/th><th scope=\"col\">Điều kiện đo<\/th><th scope=\"col\">Min<\/th><th scope=\"col\">Typ<\/th><th scope=\"col\">Max<\/th><th scope=\"col\">Đơn vị<\/th><\/tr><\/thead><tbody><tr><td>VOL<\/td><td>điện áp ra mức thấp (cổng)<\/td><td>IOL = 2 mA<\/td><td><\/td><td>0,2<\/td><td>0,40<\/td><td>V<\/td><\/tr><tr><td>VOL<\/td><td>điện áp ra mức thấp (cổng)<\/td><td>IOL = 6 mA<\/td><td><\/td><td>0,4<\/td><td>0,60<\/td><td>V<\/td><\/tr><tr><td>VOH<\/td><td>điện áp ra mức cao (cổng)<\/td><td>IOH = −80 µA<\/td><td>2,4<\/td><td><\/td><td><\/td><td>V<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Cho chân chìm 10 mA liên tục thì VOL được bảo đảm bao nhiêu?", "o": ["≤ 0,60 V", "≤ 0,40 V", "Không được bảo đảm"], "a": 2}, "say": "<p>Giới hạn tuyệt đối là mép vực, không phải đường đi. Thiết kế theo bảng điều kiện làm việc và bảng đặc tính, chừa biên; muốn dòng lớn hơn thì dùng tầng đệm (Chương 2).<\/p>"}]}, {"label": "Bẫy: Đo ở điều kiện khác bảng", "note": "4 mA không có trong bảng: không so được, đo lại ở 2 mA.", "steps": [{"t": "Đo VOL = 0,52 V khi IOL = 4 mA", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Đại lượng<\/th><th scope=\"col\">Giá trị đo (giả định)<\/th><\/tr><\/thead><tbody><tr><td>VCC<\/td><td>5,0 V<\/td><\/tr><tr><td>Nhiệt độ<\/td><td>25 °C<\/td><\/tr><tr><td>IOL đặt<\/td><td>4,0 mA<\/td><\/tr><tr><td>VOL đo<\/td><td>0,52 V<\/td><\/tr><\/tbody><\/table>", "say": "<p>Người đo so ngay với dòng đầu của bảng: 0,52 V &gt; 0,40 V, kết luận “chip hỏng”.<\/p>"}, {"t": "So với bảng: dòng nào có IOL = 4 mA?", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Ký hiệu<\/th><th scope=\"col\">Thông số<\/th><th scope=\"col\">Điều kiện đo<\/th><th scope=\"col\">Min<\/th><th scope=\"col\">Typ<\/th><th scope=\"col\">Max<\/th><th scope=\"col\">Đơn vị<\/th><\/tr><\/thead><tbody><tr><td>VOL<\/td><td>điện áp ra mức thấp (cổng)<\/td><td>IOL = 2 mA<\/td><td><\/td><td>0,2<\/td><td>0,40<\/td><td>V<\/td><\/tr><tr><td>VOL<\/td><td>điện áp ra mức thấp (cổng)<\/td><td>IOL = 6 mA<\/td><td><\/td><td>0,4<\/td><td>0,60<\/td><td>V<\/td><\/tr><tr><td>VOH<\/td><td>điện áp ra mức cao (cổng)<\/td><td>IOH = −80 µA<\/td><td>2,4<\/td><td><\/td><td><\/td><td>V<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Kết luận nào đúng?", "o": ["Không so được: bảng không có dòng 4 mA", "Không đạt", "Đạt vì nhỏ hơn 0,60 V"], "a": 0}}, {"t": "Đo lại ở đúng điều kiện bảng", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">IOL đặt<\/th><th scope=\"col\">VOL đo (giả định)<\/th><th scope=\"col\">Giới hạn<\/th><th scope=\"col\">Kết luận<\/th><\/tr><\/thead><tbody><tr><td>4 mA<\/td><td>0,52 V<\/td><td>—<\/td><td class=\"bad\">Không so được<\/td><\/tr><tr><td>2 mA<\/td><td>0,38 V<\/td><td>≤ 0,40 V<\/td><td class=\"ok\">Đạt<\/td><\/tr><\/tbody><\/table>", "say": "<p>Không nội suy giữa hai dòng của bảng để kết luận đạt / không đạt: bảng không bảo đảm gì ở 4 mA. Nếu datasheet có đồ thị VOL theo IOL thì chỉ dùng để ước lượng.<\/p>"}]}, {"label": "Bẫy: Sai biến thể chip hoặc sai phiên bản", "note": "Cùng số đo, hai phiên bản tài liệu cho hai kết luận.", "steps": [{"t": "Chạy mã -24PC ở thạch anh 33 MHz", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Mã đặt hàng<\/th><th scope=\"col\">f max<\/th><th scope=\"col\">Vỏ<\/th><th scope=\"col\">Nhiệt độ<\/th><\/tr><\/thead><tbody><tr><td>AMTS-D51-24PC<\/td><td>24 MHz<\/td><td>PDIP 40 chân<\/td><td>0 … 70 °C<\/td><\/tr><tr><td>AMTS-D51-33JI<\/td><td>33 MHz<\/td><td>PLCC 44 chân<\/td><td>-40 … 85 °C<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">33 MHz &gt; 24 MHz → các số timing không được bảo đảm<\/p>", "say": "<p>Hai biến thể cùng tên chip có thể khác tần số lớn nhất và dải nhiệt độ. Đọc mã trên thân chip thật trước khi chọn bảng.<\/p>"}, {"t": "Sai phiên bản tài liệu: VOL ở 6 mA đo 0,62 V", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Phiên bản datasheet<\/th><th scope=\"col\">Giới hạn VOL (6 mA)<\/th><th scope=\"col\">Kết luận với 0,62 V<\/th><\/tr><\/thead><tbody><tr><td>Rev. B<\/td><td>≤ 0,65 V<\/td><td>Đạt<\/td><\/tr><tr><td>Rev. C (mới)<\/td><td>≤ 0,60 V<\/td><td class=\"bad\">Không đạt<\/td><\/tr><\/tbody><\/table><p class=\"mt-cap\"><b>Giả định:<\/b> chip AMTS-D51 và mọi số trong bảng do bài tự đặt ra để luyện đọc, không phải số của chip thật.<\/p>", "ask": {"q": "Phiếu lab nên ghi gì để tránh nhầm này?", "o": ["Chỉ cần tên chip", "Mã đặt hàng và phiên bản datasheet đã dùng", "Tên trang web đã tải tài liệu"], "a": 1}, "say": "<p>Cùng một số đo, hai phiên bản tài liệu cho hai kết luận. Luôn tải tài liệu từ trang chính thức của hãng và ghi phiên bản; xem phần lịch sử sửa đổi và errata (bản đính chính) nếu có.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l12"),"l12",[{"kind": "num", "t": "Đọc bảng và tính thông số", "items": [{"q": "Giới hạn VOL khi IOL = 6 mA", "a": 0.6, "tol": 0.001, "unit": "V"}, {"q": "tCLCL ở thạch anh 24 MHz (2 chữ số thập phân)", "a": 41.67, "tol": 0.006, "unit": "ns"}, {"q": "tLHLL min = 2 tCLCL − 35 ns ở 24 MHz (2 chữ số thập phân)", "a": 48.33, "tol": 0.006, "unit": "ns"}, {"q": "1 chu kỳ máy (12 tCLCL) ở 11,0592 MHz (3 chữ số thập phân)", "a": 1.085, "tol": 0.0006, "unit": "µs"}, {"q": "Tần số thạch anh lớn nhất của mã AMTS-D51-24PC", "a": 24, "tol": 0, "unit": "MHz"}, {"q": "Đo VOL = 0,31 V ở đúng điều kiện IOL = 2 mA: còn cách giới hạn bao nhiêu", "a": 0.09, "tol": 0.001, "unit": "V"}], "hints": ["Tìm đúng dòng có điều kiện đo khớp (IOL = 6 mA), đọc cột max.", "tCLCL = 1 / f: 1 / 24 MHz = 1000 / 24 ns. Thay vào công thức k · tCLCL − c.", "Hậu tố -24 trong mã đặt hàng là tần số lớn nhất. Biên an toàn = giới hạn − số đo."], "why": "VOL ≤ 0,60 V ở 6 mA; tCLCL = 1000 / 24 = 41,67 ns; 2 × 41,67 − 35 = 48,33 ns; 12 / 11,0592 MHz = 1,085 µs (ucsim s51 đo 12 chu kỳ dao động = 1,085e-06 s); -24 → 24 MHz; 0,40 − 0,31 = 0,09 V.", "d": "<p>Dùng các bảng của chip giả định AMTS-D51 ở mục 12.1–12.2 (bảng đặc tính DC, bảng AC, mã đặt hàng). Số thập phân viết dấu phẩy hoặc dấu chấm đều được.<\/p><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Ký hiệu<\/th><th scope=\"col\">Thông số<\/th><th scope=\"col\">Điều kiện đo<\/th><th scope=\"col\">Min<\/th><th scope=\"col\">Typ<\/th><th scope=\"col\">Max<\/th><th scope=\"col\">Đơn vị<\/th><\/tr><\/thead><tbody><tr><td>VOL<\/td><td>điện áp ra mức thấp (cổng)<\/td><td>IOL = 2 mA<\/td><td><\/td><td>0,2<\/td><td>0,40<\/td><td>V<\/td><\/tr><tr><td>VOL<\/td><td>điện áp ra mức thấp (cổng)<\/td><td>IOL = 6 mA<\/td><td><\/td><td>0,4<\/td><td>0,60<\/td><td>V<\/td><\/tr><tr><td>VOH<\/td><td>điện áp ra mức cao (cổng)<\/td><td>IOH = −80 µA<\/td><td>2,4<\/td><td><\/td><td><\/td><td>V<\/td><\/tr><\/tbody><\/table><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Ký hiệu<\/th><th scope=\"col\">Thông số<\/th><th scope=\"col\">Min<\/th><th scope=\"col\">Max<\/th><\/tr><\/thead><tbody><tr><td>1/tCLCL<\/td><td>tần số thạch anh, mã -24<\/td><td>0<\/td><td>24 MHz<\/td><\/tr><tr><td>tLHLL<\/td><td>độ rộng xung ALE<\/td><td>2tCLCL − 35 ns<\/td><td><\/td><\/tr><tr><td>tAVLL<\/td><td>địa chỉ ổn định trước khi ALE xuống<\/td><td>tCLCL − 20 ns<\/td><td><\/td><\/tr><\/tbody><\/table>"}, {"kind": "pick", "t": "Kết luận một phép đo", "cats": ["Đạt", "Không đạt", "Không so được", "Vượt giới hạn tuyệt đối"], "items": [{"q": "VOL ở IOL = 2 mA, VCC = 5,0 V, 25 °C: đo 0,31 V", "a": 0}, {"q": "VOL ở IOL = 2 mA, VCC = 5,0 V, 25 °C: đo 0,47 V", "a": 1}, {"q": "VOL đo 0,52 V khi IOL = 4 mA (VCC 5,0 V, 25 °C)", "a": 2}, {"q": "VOH ở IOH = −80 µA, VCC = 5,0 V, 25 °C: đo 2,1 V", "a": 1}, {"q": "VOL ở IOL = 2 mA đo 0,35 V, nhưng VCC lúc đo là 4,2 V", "a": 2}, {"q": "Mã C (0…70 °C), VOL ở IOL = 6 mA, VCC = 5,0 V, trong lò 85 °C: đo 0,55 V", "a": 2}, {"q": "Cho dòng 12 mA chảy vào một chân cổng để thử VOL", "a": 3}, {"q": "Đặt nguồn VCC = 7,0 V để thử chip có chịu được không", "a": 3}, {"q": "VOH ở IOH = −80 µA, VCC = 4,5 V, 0 °C: đo đúng 2,4 V", "a": 0}], "hints": ["Thứ tự kiểm tra: có vượt giới hạn tuyệt đối không → VCC, nhiệt độ có trong điều kiện làm việc không → điều kiện đo có khớp dòng bảng không → so với min / max.", "Bảng chỉ bảo đảm ở đúng điều kiện ghi trong bảng. Khác dòng tải, khác VCC, khác dải nhiệt độ của mã chip: không so được, phải đo lại.", "Bằng đúng giới hạn (min 2,4 V, đo 2,4 V) vẫn là đạt."], "why": "0,31 ≤ 0,40: đạt; 0,47 > 0,40: không đạt; 4 mA không có trong bảng (chỉ 2 và 6 mA): không so được; 2,1 < 2,4: không đạt; VCC 4,2 V ngoài 4,5…5,5 V: không so được; 85 °C ngoài 0…70 °C của mã C: không so được; 12 mA > 10 mA và 7,0 V > 6,5 V: vượt giới hạn tuyệt đối, có thể làm hỏng chip; 2,4 = min: đạt.", "d": "<p>Chip giả định AMTS-D51 mã …C (0…70 °C). Kết luận từng phép đo theo bốn bảng ở mục 12.1. Thứ tự kiểm tra: giới hạn tuyệt đối → điều kiện làm việc → điều kiện đo của dòng bảng → min / max.<\/p>"}, {"kind": "order", "t": "Sắp xếp các mục của phiếu lab", "items": ["Mục tiêu: đo gì, để trả lời câu hỏi nào", "Linh kiện và tài liệu: mã đặt hàng đầy đủ, tên và phiên bản datasheet", "Sơ đồ và điều kiện đo: VCC, nhiệt độ, dòng tải, dụng cụ đo và thang đo", "Dự đoán: giá trị tính trước và giới hạn đọc từ datasheet", "Dữ liệu thô: mọi lần đo, có đơn vị, không sửa xóa", "So sánh: số đo với dự đoán và với giới hạn, biên an toàn hoặc sai số", "Kết luận và giới hạn của phép đo"], "hints": ["Phải biết mình đo chip nào, theo tài liệu nào, trước khi vẽ sơ đồ.", "Dự đoán viết trước khi đo; dữ liệu thô ghi ngay khi đo.", "Kết luận chỉ đến sau khi so sánh, và phải nói rõ phép đo còn giới hạn gì."], "why": "Mục tiêu → linh kiện, tài liệu (đúng mã, đúng phiên bản) → sơ đồ, điều kiện đo → dự đoán → dữ liệu thô → so sánh → kết luận và giới hạn. Thứ tự này để người khác tái lập được phép đo.", "d": "<p>Đưa các mục của một phiếu lab về đúng thứ tự từ trên xuống bằng nút ↑ ↓.<\/p>"}]);

makeQuiz("quiz12","score12",[{"q": "Bảng giới hạn tuyệt đối (Absolute Maximum Ratings) của chip giả định ghi dòng mỗi chân 10 mA. Điều đó nghĩa là gì?", "o": ["Chip được thiết kế để làm việc lâu dài ở 10 mA mỗi chân, đó là dòng định mức", "10 mA là giá trị điển hình của dòng chân khi cổng ra ở mức logic thấp", "Có thể vượt 10 mA trong thời gian ngắn mà không ảnh hưởng tới tuổi thọ chip", "Không được vượt 10 mA; ở mức đó chip không được bảo đảm hoạt động đúng"], "a": 3, "e": "Giới hạn tuyệt đối là ngưỡng có thể gây hỏng, không phải điều kiện làm việc. Điều kiện bảo đảm nằm ở bảng điều kiện làm việc và bảng đặc tính (ở đây VOL chỉ được bảo đảm tới 6 mA)."}, {"q": "Một dòng của bảng đặc tính có ba cột Min, Typ, Max. Khi thiết kế, cột nào được dùng làm giới hạn?", "o": ["Typ, vì đó là giá trị gặp nhiều nhất khi đo trên nhiều chip", "Min hoặc Max (cột có ghi số); Typ chỉ để ước lượng", "Trung bình cộng của Min và Max, để cân bằng hai phía", "Cột có số lớn nhất, để thiết kế luôn có dự phòng"], "a": 1, "e": "Nhà sản xuất bảo đảm Min/Max trong điều kiện ghi kèm; Typ thường chỉ là giá trị đo trên mẫu ở điều kiện danh định, không được bảo đảm. Thiết kế theo Typ thì một số chip sẽ không đạt."}, {"q": "Công thức giả định tAVLL min = tCLCL − 20 ns. Ở thạch anh 33 MHz, tAVLL min bằng bao nhiêu?", "o": ["30,3 ns", "50,3 ns", "21,7 ns", "10,3 ns"], "a": 3, "e": "tCLCL = 1000 / 33 = 30,3 ns; 30,3 − 20 = 10,3 ns. 30,3 là quên trừ; 50,3 là cộng thay vì trừ; 21,7 ns là tính ở 24 MHz."}, {"q": "Đo VOL = 0,52 V khi IOL = 4 mA. Bảng chỉ có VOL ≤ 0,40 V ở 2 mA và VOL ≤ 0,60 V ở 6 mA. Kết luận nào đúng?", "o": ["Không đạt vì 0,52 V lớn hơn giới hạn 0,40 V ở 2 mA", "Đạt vì 0,52 V vẫn nhỏ hơn giới hạn 0,60 V ở 6 mA", "Chưa kết luận được với bảng này: đo lại ở 2 mA hoặc 6 mA", "Chip đã hỏng vì VOL cao, phải thay chip khác rồi đo lại"], "a": 2, "e": "Bảng chỉ bảo đảm ở đúng điều kiện ghi kèm. 4 mA không có trong bảng nên không so được; muốn kết luận phải đo lại ở điều kiện của bảng (hoặc dùng đồ thị đặc tính nếu datasheet có)."}, {"q": "Phiếu lab nào cho phép người khác làm lại đúng phép đo?", "o": ["“AMTS-D51-24PC, datasheet Rev. C; VCC = 5,0 V, 25 °C; IOL = 2,0 mA; đồng hồ thang 2 V; VOL = 0,31 V”", "“Đo chân P1.0 của chip 8051 bằng đồng hồ số thấy khoảng 0,3 V, chip chạy ổn định, kết luận đạt”", "“VOL = 0,31 (đạt); chip 8051 loại thường; nguồn bình thường; nhiệt độ phòng; đo nhanh hai lần”", "“Đo VOL theo datasheet mới nhất của hãng; kết quả tốt hơn giới hạn trong bảng; xem ảnh đính kèm”"], "a": 0, "e": "Tái lập được cần: mã chip và phiên bản tài liệu, điều kiện đo (VCC, nhiệt độ, dòng tải), dụng cụ, số đo có đơn vị. Các phiếu còn lại thiếu đơn vị, điều kiện hoặc tên chip đúng."}]);

fillSnips();
